{
    "$schema": "http://json-schema.org/draft-07/schema#",
    "name": "music_song_search",
    "description": "酷狗音乐搜索工具(music_song_search)。当用户表达搜索歌曲、找歌、听某首歌等需要指定具体搜索条件的意图时触发。支持歌曲名、歌手、专辑、作词、作曲、版本、性别、影视IP、歌词、榜单、标签等维度筛选，所有条件间为 AND 关系。",
    "type": "object",
    "properties": {
        "query": {
            "type": "array",
            "description": "搜索条件列表。所有条件之间为 AND 关系。每个元素代表一个搜索维度的匹配条件。",
            "items": {
                "$ref": "#/definitions/FieldCondition"
            },
            "minItems": 1
        }
    },
    "required": [
        "query"
    ],
    "additionalProperties": false,
    "definitions": {
        "FieldCondition": {
            "description": "搜索维度条件。field 指定维度，value 指定匹配值。",
            "type": "object",
            "properties": {
                "field": {
                    "type": "string",
                    "enum": [
                        "song",
                        "singer",
                        "album",
                        "lyricist",
                        "composer",
                        "version",
                        "gender",
                        "ip",
                        "lyrics",
                        "toplist",
                        "tag"
                    ],
                    "description": "音乐搜索维度字段名。"
                },
                "value": {
                    "type": "string",
                    "description": "精确匹配值。同一维度有多个值时，在数组中添加多个条件元素。"
                }
            },
            "required": [
                "field",
                "value"
            ],
            "additionalProperties": false
        }
    }
}

{
    "$schema": "http://json-schema.org/draft-07/schema#",
    "name": "music_song_qqmusic_search",
    "description": "QQ音乐搜索工具(music_song_qqmusic_search)。当用户表达在QQ音乐中搜索歌曲的意图时触发。支持歌曲名、歌手、影视IP、榜单、标签5个维度，其余维度会被忽略。所有条件间为 AND 关系。",
    "type": "object",
    "properties": {
        "query": {
            "type": "array",
            "description": "搜索条件列表。仅支持歌曲名、歌手、影视IP、榜单、标签5个维度，其余维度会被忽略。所有条件间为 AND 关系。",
            "items": {
                "$ref": "#/definitions/FieldCondition"
            },
            "minItems": 1
        }
    },
    "required": [
        "query"
    ],
    "additionalProperties": false,
    "definitions": {
        "FieldCondition": {
            "description": "搜索维度条件。field 指定维度，value 指定匹配值。",
            "type": "object",
            "properties": {
                "field": {
                    "type": "string",
                    "enum": [
                        "song",
                        "singer",
                        "ip",
                        "toplist",
                        "tag"
                    ],
                    "description": "QQ音乐搜索维度字段名。"
                },
                "value": {
                    "type": "string",
                    "description": "精确匹配值。"
                }
            },
            "required": [
                "field",
                "value"
            ],
            "additionalProperties": false
        }
    }
}

