{
    "$schema": "http://json-schema.org/draft-07/schema#",
    "name": "music_ksong_search",
    "description": "全民K歌搜索工具(music_qm_ksong_search)。当用户表达在全民K歌中搜索歌曲的意图时触发。支持歌曲名、歌手、专辑、作词、作曲、版本、性别、影视IP、歌词、榜单、标签、原始关键词、语言等全部语义维度，所有条件间为 AND 关系。",
    "type": "object",
    "properties": {
        "query": {
            "type": "array",
            "description": "搜索条件列表。所有条件之间为 AND 关系。",
            "items": {
                "$ref": "#/definitions/FieldCondition"
            },
            "minItems": 1
        }
    },
    "required": [
        "query"
    ],
    "additionalProperties": false,
    "definitions": {
        "FieldCondition": {
            "description": "搜索维度条件。field 指定维度，value 指定匹配值。",
            "type": "object",
            "properties": {
                "field": {
                    "type": "string",
                    "enum": [
                        "song",
                        "singer",
                        "album",
                        "lyricist",
                        "composer",
                        "version",
                        "gender",
                        "ip",
                        "lyrics",
                        "toplist",
                        "tag",
                        "keyword",
                        "lang"
                    ],
                    "description": "全民K歌搜索维度字段名。"
                },
                "value": {
                    "type": "string",
                    "description": "精确匹配值。"
                }
            },
            "required": [
                "field",
                "value"
            ],
            "additionalProperties": false
        }
    }
}

{
    "$schema": "http://json-schema.org/draft-07/schema#",
    "name": "music_qa",
    "description": "音乐问答与搜索工具(music_qa)。当用户表达了音乐相关查询意图时触发，包括：歌曲基础信息查询、歌手/乐队信息查询、专辑信息查询、音乐模糊搜索。支持 singer(歌手)、song(歌曲)、album(专辑)、lyricist(作词)、composer(作曲)、version(版本)、gender(性别)、ip(影视IP)、lyrics(歌词)、toplist(榜单)、tag(风格标签)、lang(语言)、keyword(关键词) 共13个搜索维度。同一维度多值时通过 values 数组传入。slots 非空时 keyword 不参与检索。",
    "type": "object",
    "properties": {
        "intent": {
            "type": "string",
            "description": "意图类型。music_song_info_qa：歌曲基础信息查询；music_song_singer_info_qa：歌手/乐队信息查询；music_song_ablum_info_qa：专辑信息查询；music_song_fuzzy_search：音乐模糊搜索。",
            "enum": [
                "music_song_info_qa",
                "music_song_singer_info_qa",
                "music_song_ablum_info_qa",
                "music_song_fuzzy_search"
            ]
        },
        "normalText": {
            "type": "string",
            "description": "用户语音转文本后的原始语句，如'周杰伦的晴天是哪年发行的'、'叶惠美专辑里有哪些歌'。"
        },
        "slots": {
            "type": "array",
            "description": "从 normalText 中提取的结构化槽位列表。每个元素描述一个搜索维度的匹配条件。slots 非空时优先以槽位检索，keyword 不参与检索。",
            "items": {
                "$ref": "#/definitions/SlotItem"
            },
            "minItems": 1
        }
    },
    "required": [
        "intent",
        "normalText"
    ],
    "additionalProperties": false,
    "definitions": {
        "SlotItem": {
            "description": "单个槽位条目，描述对某一搜索维度的匹配条件。field 指定维度，value 为单值精确匹配，values 为多值匹配。",
            "type": "object",
            "properties": {
                "field": {
                    "type": "string",
                    "enum": [
                        "singer",
                        "song",
                        "album",
                        "lyricist",
                        "composer",
                        "version",
                        "gender",
                        "ip",
                        "lyrics",
                        "toplist",
                        "tag",
                        "lang",
                        "keyword"
                    ],
                    "description": "搜索维度字段名。singer：歌手/乐队；song：歌曲名；album：专辑名；lyricist：作词人；composer：作曲人；version：歌曲版本如现场版/翻唱版；gender：歌手性别；ip：影视IP名称；lyrics：歌词片段；toplist：榜单名称；tag：音乐风格/标签，当 slots 仅含 tag 时自动切换为 keyword 检索；lang：语言如粤语/国语/英语；keyword：关键词，不作为槽位条件输出，仅用于关键词检索模式。"
                },
                "value": {
                    "type": "string",
                    "description": "单值精确匹配。"
                },
                "values": {
                    "type": "array",
                    "items": {
                        "type": "string"
                    },
                    "minItems": 1,
                    "description": "多值匹配，逻辑关系由 operator 字段决定。"
                },
                "operator": {
                    "type": "string",
                    "enum": [
                        "and",
                        "or"
                    ],
                    "default": "or",
                    "description": "维度内多值逻辑关系。'or' 表示任一值匹配即命中(默认)，'and' 表示所有值均需匹配。仅在使用 values 时生效。"
                }
            },
            "required": [
                "field"
            ],
            "oneOf": [
                {
                    "required": ["value"]
                },
                {
                    "required": ["values"]
                }
            ],
            "additionalProperties": false
        }
    }
}

{
  "name": "music_slow_search_data_search",
  "title": "音乐模糊语料搜索",
  "description": "功能：当用户询问的语料过于模糊，无法从中提取出准确的歌曲名、歌手、专辑、作词、作曲、版本、性别、影视IP、歌词、榜单等结构化信息时，直接将用户原始输入作为关键词进行搜索参考，返回相关歌曲候选结果。\n适用场景：用户以场景、情绪、节日、氛围等描述性语言表达找歌需求，无法提取任何明确槽位信息，如"最近失眠，晚上总睡不着，有什么音乐能帮忙吗"、"春节的时候适合听什么歌曲"等。\n不适用场景：当可以从用户语料中提取出歌曲名、歌手、专辑、作词、作曲、版本、性别、影视IP、歌词、榜单等任一准确槽位时，应使用 music_song_search 工具而非本工具。\n关联工具：可提取明确槽位时用 music_song_search。\n结果使用：将返回的歌曲候选列表展示给用户供选择或直接播放。",
  "parameters": {
    "type": "object",
    "properties": {
      "keyword": {
        "type": "string",
        "description": "用户原始输入的完整语料文本，不做任何提取或修改，直接透传。"
      }
    },
    "required": ["keyword"]
  },
  "output": {
    "type": "object",
    "properties": {
      "songs": {
        "type": "array",
        "description": "搜索返回的歌曲候选列表",
        "items": {
          "type": "object",
          "properties": {
            "song_id": {"type": "string", "description": "歌曲唯一标识ID"},
            "song_name": {"type": "string", "description": "歌曲名称"},
            "singer_name": {"type": "string", "description": "歌手名称"},
            "album_name": {"type": "string", "description": "所属专辑名称"},
            "duration": {"type": "integer", "description": "歌曲时长，单位秒"},
            "cover_url": {"type": "string", "description": "歌曲封面图片URL"}
          }
        }
      },
      "total": {"type": "integer", "description": "搜索结果总数"}
    },
    "usage_hint": "将歌曲候选列表展示给用户供选择，或直接播放第一条结果"
  },
  "error_output": {
    "type": "object",
    "properties": {
      "error_code": {"type": "string", "description": "错误码，如NO_RESULT"},
      "error_message": {"type": "string", "description": "错误描述信息"}
    }
  },
  "examples": [
    {
      "scenario": "场景/情绪驱动的模糊找歌——助眠场景",
      "input": {"keyword": "最近失眠，晚上总睡不着，有什么音乐能帮忙吗"},
      "output": {
        "songs": [
          {"song_id": "112233", "song_name": "夜的钢琴曲五", "singer_name": "石进", "album_name": "夜的钢琴曲", "duration": 214, "cover_url": "https://xxx.com/cover/112233.jpg"},
          {"song_id": "445566", "song_name": "星空", "singer_name": "班得瑞", "album_name": "仙境", "duration": 268, "cover_url": "https://xxx.com/cover/445566.jpg"}
        ],
        "total": 2
      }
    },
    {
      "scenario": "节日氛围驱动的模糊找歌——春节场景",
      "input": {"keyword": "春节的时候适合听什么歌曲"},
      "output": {
        "songs": [
          {"song_id": "778899", "song_name": "恭喜恭喜", "singer_name": "姚莉", "album_name": "恭喜恭喜", "duration": 183, "cover_url": "https://xxx.com/cover/778899.jpg"},
          {"song_id": "998877", "song_name": "新年好", "singer_name": "群星", "album_name": "新年好", "duration": 156, "cover_url": "https://xxx.com/cover/998877.jpg"}
        ],
        "total": 2
      }
    },
    {
      "scenario": "无搜索结果",
      "input": {"keyword": "那个什么什么的歌"},
      "output": {"error_code": "NO_RESULT", "error_message": "未找到相关歌曲"}
    }
  ]
}
